package com.netshaper.mobile.engine

import android.content.Context
import org.json.JSONObject
import java.lang.reflect.InvocationTargetException
import java.lang.reflect.Method
import java.lang.reflect.Proxy
import java.util.concurrent.atomic.AtomicBoolean

/**
 * 1-to-1 reflective bridge to `mobilecore.Mobilecore` & `mobilecore.MobileCallback` generated by
 * `gomobile bind` inside `app/libs/netshaper-core.aar`.
 *
 * All reflective lookups, native `libgojni.so` loading, and `go.Seq.setContext` initialization
 * occur strictly off the UI thread.
 */
class GoMobileNetShaperEngine : NetShaperEngine {

    private class Bindings {
        val coreClass: Class<*> = Class.forName("mobilecore.Mobilecore")
        val callbackIface: Class<*> = Class.forName("mobilecore.MobileCallback")

        val mStart: Method = coreClass.getMethod("start", String::class.java, callbackIface)
        val mStop: Method = coreClass.getMethod("stop")
        val mGetSnapshotJSON: Method = coreClass.getMethod("getSnapshotJSON")
        val mGetLogsJSON: Method = coreClass.getMethod("getLogsJSON", Long::class.javaPrimitiveType)
        val mClearLogs: Method = coreClass.getMethod("clearLogs")
        val mNotifyNetworkChange: Method = coreClass.getMethod(
            "notifyNetworkChange",
            String::class.java,
            Boolean::class.javaPrimitiveType
        )
        val mSetAppForeground: Method = coreClass.getMethod("setAppForeground", Boolean::class.javaPrimitiveType)
        val mStartDeviceAuthJSON: Method = coreClass.getMethod("startDeviceAuthJSON", String::class.java)
        val mPollDeviceAuthJSON: Method = coreClass.getMethod("pollDeviceAuthJSON", String::class.java, String::class.java)
        val mListCodespacesJSON: Method = coreClass.getMethod("listCodespacesJSON", String::class.java)
        val mCheckQuotaJSON: Method = coreClass.getMethod("checkQuotaJSON", String::class.java, String::class.java)
        val mStopCodespaceNow: Method = coreClass.getMethod("stopCodespaceNow", String::class.java, String::class.java)
        val mGetV2RayNGProfileURI: Method = coreClass.getMethod("getV2RayNGProfileURI")
        val mCoreVersion: Method = coreClass.getMethod("coreVersion")
    }

    private val bindings: Bindings by lazy {
        try {
            Bindings()
        } catch (t: Throwable) {
            throw IllegalStateException(
                "netshaper-core.aar or libgojni.so failed to load for this device ABI.",
                t
            )
        }
    }

    private inline fun <T> invokeGo(block: (Bindings) -> T): Result<T> = try {
        Result.success(block(bindings))
    } catch (ite: InvocationTargetException) {
        Result.failure(ite.targetException ?: ite)
    } catch (t: Throwable) {
        Result.failure(t)
    }

    override fun start(configJson: String, callback: NetShaperCallback): Result<Unit> = invokeGo { b ->
        val proxyCallback = Proxy.newProxyInstance(
            b.callbackIface.classLoader,
            arrayOf(b.callbackIface)
        ) { proxy, method, args ->
            when (method.name) {
                "onStateChange" -> {
                    callback.onStateChange(
                        args?.getOrNull(0) as? String ?: "",
                        args?.getOrNull(1) as? String ?: ""
                    )
                    null
                }
                "onLogLine" -> {
                    callback.onLogLine(
                        (args?.getOrNull(0) as? Number)?.toLong() ?: 0L,
                        args?.getOrNull(1) as? String ?: "INFO",
                        args?.getOrNull(2) as? String ?: ""
                    )
                    null
                }
                "onError" -> {
                    callback.onError(
                        args?.getOrNull(0) as? String ?: "error",
                        args?.getOrNull(1) as? String ?: ""
                    )
                    null
                }
                "equals" -> proxy === args?.getOrNull(0)
                "hashCode" -> System.identityHashCode(proxy)
                "toString" -> "GoMobileCallbackProxy"
                else -> null
            }
        }
        b.mStart.invoke(null, configJson, proxyCallback)
        Unit
    }

    override fun stop(): Result<Unit> = invokeGo { b ->
        b.mStop.invoke(null)
        Unit
    }

    override fun getSnapshotJson(): String = invokeGo { b ->
        b.mGetSnapshotJSON.invoke(null) as? String ?: """{"state":"STOPPED"}"""
    }.getOrElse { err ->
        JSONObject().apply {
            put("state", "STOPPED")
            put("last_error", err.message ?: "Go core snapshot unavailable")
        }.toString()
    }

    override fun getLogsJson(sinceSeq: Long): String = invokeGo { b ->
        b.mGetLogsJSON.invoke(null, sinceSeq) as? String ?: "[]"
    }.getOrElse { "[]" }

    override fun clearLogs() {
        invokeGo { b -> b.mClearLogs.invoke(null) }
    }

    override fun notifyNetworkChange(networkType: String, isMetered: Boolean) {
        invokeGo { b -> b.mNotifyNetworkChange.invoke(null, networkType, isMetered) }
    }

    override fun setAppForeground(inForeground: Boolean) {
        invokeGo { b -> b.mSetAppForeground.invoke(null, inForeground) }
    }

    override fun startDeviceAuthJson(clientId: String): Result<String> = invokeGo { b ->
        b.mStartDeviceAuthJSON.invoke(null, clientId) as String
    }

    override fun pollDeviceAuthJson(clientId: String, deviceCode: String): Result<String> = invokeGo { b ->
        b.mPollDeviceAuthJSON.invoke(null, clientId, deviceCode) as String
    }

    override fun listCodespacesJson(token: String): Result<String> = invokeGo { b ->
        b.mListCodespacesJSON.invoke(null, token) as String
    }

    override fun checkQuotaJson(token: String, codespaceName: String): Result<String> = invokeGo { b ->
        b.mCheckQuotaJSON.invoke(null, token, codespaceName) as String
    }

    override fun stopCodespaceNow(token: String, codespaceName: String): Result<Unit> = invokeGo { b ->
        b.mStopCodespaceNow.invoke(null, token, codespaceName)
        Unit
    }

    override fun getV2RayNGProfileURI(): String = invokeGo { b ->
        b.mGetV2RayNGProfileURI.invoke(null) as? String ?: "socks://127.0.0.1:1080#NetShaper"
    }.getOrElse { "socks://127.0.0.1:1080#NetShaper" }

    override fun coreVersion(): String = invokeGo { b ->
        b.mCoreVersion.invoke(null) as? String ?: "v7.0-mobile-core6.4"
    }.getOrElse { "v7.0-mobile-core6.4 (native core init failed)" }

    companion object {
        private val goContextInitialized = AtomicBoolean(false)

        /**
         * Checks whether `netshaper-core.aar` is linked WITHOUT running static initializers
         * (zero `System.loadLibrary("gojni")` on Main thread).
         */
        fun isAarPresent(): Boolean = runCatching {
            Class.forName(
                "mobilecore.Mobilecore",
                false,
                GoMobileNetShaperEngine::class.java.classLoader
            )
            true
        }.getOrDefault(false)

        /**
         * Initializes `go.Seq.setContext(appContext)` on a background IO thread prior to any Go call.
         */
        fun setGoAndroidContext(context: Context): Boolean {
            if (!isAarPresent()) return false
            if (goContextInitialized.get()) return true
            return runCatching {
                val seqCls = Class.forName("go.Seq")
                val setCtx = seqCls.getMethod("setContext", Context::class.java)
                setCtx.invoke(null, context.applicationContext)
                goContextInitialized.set(true)
                true
            }.getOrDefault(false)
        }
    }
}
